-- SQL practice schemas and seed data (MySQL 8 syntax; PostgreSQL: change DATETIME to TIMESTAMP)

-- ===== HR: HR / Employee Database =====
CREATE TABLE departments (
  dept_id INT PRIMARY KEY, dept_name VARCHAR(50) NOT NULL, location VARCHAR(50));
CREATE TABLE employees (
  emp_id INT PRIMARY KEY, emp_name VARCHAR(80) NOT NULL, email VARCHAR(100),
  dept_id INT, manager_id INT, job_title VARCHAR(60), salary INT NOT NULL,
  commission INT, hire_date DATE NOT NULL, city VARCHAR(50),
  FOREIGN KEY (dept_id) REFERENCES departments(dept_id),
  FOREIGN KEY (manager_id) REFERENCES employees(emp_id));
CREATE TABLE projects (
  project_id INT PRIMARY KEY, project_name VARCHAR(60), dept_id INT,
  start_date DATE, end_date DATE);
CREATE TABLE emp_projects (
  emp_id INT, project_id INT, hours INT, PRIMARY KEY (emp_id, project_id));

