-- ===== CAMPUS: Campus / Student Database =====
CREATE TABLE students (
  student_id INT PRIMARY KEY, student_name VARCHAR(80), dept VARCHAR(10),
  admission_year INT, city VARCHAR(50), age INT);
CREATE TABLE courses (
  course_id INT PRIMARY KEY, course_name VARCHAR(80), credits INT, dept VARCHAR(10));
CREATE TABLE enrollments (
  enroll_id INT PRIMARY KEY, student_id INT, course_id INT, marks INT, semester INT);

