-- ===== SHOP: E-commerce (Amazon / Flipkart / Myntra / Meesho style) =====
CREATE TABLE customers (
  customer_id INT PRIMARY KEY, customer_name VARCHAR(80), email VARCHAR(100),
  city VARCHAR(50), state VARCHAR(50), signup_date DATE, is_prime INT);
CREATE TABLE products (
  product_id INT PRIMARY KEY, product_name VARCHAR(100), category VARCHAR(40),
  brand VARCHAR(40), price DECIMAL(10,2), stock INT);
CREATE TABLE orders (
  order_id INT PRIMARY KEY, customer_id INT, order_date DATE,
  status VARCHAR(20), payment_mode VARCHAR(20));
CREATE TABLE order_items (
  order_item_id INT PRIMARY KEY, order_id INT, product_id INT,
  quantity INT, unit_price DECIMAL(10,2));
CREATE TABLE reviews (
  review_id INT PRIMARY KEY, product_id INT, customer_id INT,
  rating INT, review_date DATE);

