-- ===== FOOD: Food Delivery (Swiggy / Zomato style) =====
CREATE TABLE food_users (
  user_id INT PRIMARY KEY, user_name VARCHAR(80), city VARCHAR(50),
  signup_date DATE, is_pro INT);
CREATE TABLE restaurants (
  restaurant_id INT PRIMARY KEY, restaurant_name VARCHAR(80), city VARCHAR(50),
  cuisine VARCHAR(40), avg_rating DECIMAL(3,2), opened_date DATE);
CREATE TABLE riders (
  rider_id INT PRIMARY KEY, rider_name VARCHAR(80), city VARCHAR(50), joined_date DATE);
CREATE TABLE food_orders (
  order_id INT PRIMARY KEY, user_id INT, restaurant_id INT, rider_id INT,
  order_ts DATETIME, order_value INT, discount INT, delivery_minutes INT,
  status VARCHAR(20), rating INT);

