-- ===== BANK: Banking & Loans (BFSI style) =====
CREATE TABLE bank_customers (
  cust_id INT PRIMARY KEY, cust_name VARCHAR(80), city VARCHAR(50),
  kyc_status VARCHAR(20), joined_date DATE);
CREATE TABLE accounts (
  account_id INT PRIMARY KEY, cust_id INT, account_type VARCHAR(20),
  balance DECIMAL(12,2), opened_date DATE, branch VARCHAR(40));
CREATE TABLE transactions (
  txn_id INT PRIMARY KEY, account_id INT, txn_date DATE, txn_type VARCHAR(10),
  amount DECIMAL(12,2), channel VARCHAR(10), status VARCHAR(10));
CREATE TABLE loans (
  loan_id INT PRIMARY KEY, cust_id INT, principal DECIMAL(12,2),
  interest_rate DECIMAL(4,2), tenure_months INT, disbursed_date DATE, status VARCHAR(10));

