-- ===== PAY: Payments (PhonePe / Paytm / Razorpay style) =====
CREATE TABLE merchants (
  merchant_id INT PRIMARY KEY, merchant_name VARCHAR(80), category VARCHAR(30),
  city VARCHAR(50), onboarded_date DATE);
CREATE TABLE payments (
  payment_id INT PRIMARY KEY, merchant_id INT, user_id INT, pay_date DATE,
  amount DECIMAL(10,2), method VARCHAR(15), status VARCHAR(10));

