-- ===== FIN: Trading & Market Data (Goldman / JPM / Morgan Stanley style) =====
CREATE TABLE stock_prices (
  symbol VARCHAR(10), price_date DATE, close_price DECIMAL(10,2), volume INT,
  PRIMARY KEY (symbol, price_date));
CREATE TABLE traders (
  trader_id INT PRIMARY KEY, trader_name VARCHAR(60), desk VARCHAR(30));
CREATE TABLE trades (
  trade_id INT PRIMARY KEY, trader_id INT, symbol VARCHAR(10), trade_date DATE,
  side VARCHAR(4), quantity INT, price DECIMAL(10,2));

