-- ===== RIDES: Ride Hailing (Uber / Ola style) =====
CREATE TABLE ride_users (
  rider_id INT PRIMARY KEY, rider_name VARCHAR(80), signup_date DATE);
CREATE TABLE drivers (
  driver_id INT PRIMARY KEY, driver_name VARCHAR(80), city VARCHAR(50),
  joined_date DATE, rating DECIMAL(3,2));
CREATE TABLE rides (
  ride_id INT PRIMARY KEY, rider_id INT, driver_id INT, city VARCHAR(50),
  request_ts DATETIME, distance_km DECIMAL(5,1), fare DECIMAL(8,2), status VARCHAR(20));

