-- ===== APP: Product Analytics & SaaS Subscriptions (Microsoft / Google / Freshworks / Zoho style) =====
CREATE TABLE app_users (
  user_id INT PRIMARY KEY, signup_date DATE, country VARCHAR(5), plan VARCHAR(15));
CREATE TABLE logins (
  user_id INT, login_date DATE, PRIMARY KEY (user_id, login_date));
CREATE TABLE events (
  event_id INT PRIMARY KEY, user_id INT, event_ts DATETIME, event_type VARCHAR(20));
CREATE TABLE subscriptions (
  sub_id INT PRIMARY KEY, user_id INT, plan VARCHAR(15), start_date DATE,
  end_date DATE, monthly_fee INT);

