-- ===== CRICKET: Cricket League (fictional teams) =====
CREATE TABLE teams (
  team_id INT PRIMARY KEY, team_name VARCHAR(40), city VARCHAR(40));
CREATE TABLE matches (
  match_id INT PRIMARY KEY, match_date DATE, team1_id INT, team2_id INT,
  winner_id INT, venue VARCHAR(40));
CREATE TABLE players (
  player_id INT PRIMARY KEY, player_name VARCHAR(60), team_id INT, role VARCHAR(20));
CREATE TABLE player_performance (
  match_id INT, player_id INT, runs INT, balls INT, wickets INT,
  PRIMARY KEY (match_id, player_id));

