-- ===== MISC: Utility Tables (duplicates & sequences) =====
CREATE TABLE contacts (
  contact_id INT PRIMARY KEY, full_name VARCHAR(80), email VARCHAR(100),
  phone VARCHAR(15), created_date DATE);
